from PIL import Image
import numpy as np, cv2
im=np.array(Image.open('first_frame.png').convert('RGB'))
r,g,b=im.transpose(2,0,1)
lum=im.mean(2)
# dark object masks excluding ball: rows; print intervals below threshold, large runs
for th in [35,55,80]:
 print('\\nTH',th)
 for y in range(220,621,20):
  m=lum[y]<th
  # remove orange pixels
  m &= ~((r[y]>100)&(r[y]>g[y]*1.35))
  xs=np.where(m)[0]; runs=[]
  if len(xs):
   s=p=xs[0]
   for x in xs[1:]:
    if x>p+1:
     if p-s>=8:runs.append((int(s),int(p)))
     s=x
    p=x
   if p-s>=8:runs.append((int(s),int(p)))
  print(y,runs)
# detect strong edges via canny, line segments
ed=cv2.Canny(im,60,140)
lines=cv2.HoughLinesP(ed,1,np.pi/180,threshold=60,minLineLength=70,maxLineGap=15)
print('\\nlines')
if lines is not None:
 for l in sorted(lines[:,0].tolist(), key=lambda q:-((q[2]-q[0])**2+(q[3]-q[1])**2))[:60]: print(l)
PY"
